            "question": "๑.๕.๗.๑. สามารถบันทึกข้อมูลการสั่งการรักษาจากแพทย์เป็นชุดคำสั่ง (Order set) โดยในหนึ่งชุดคำสั่งสามารถประกอบไปด้วยคำสั่ง Lab, X-ray, หัตถการ และ Medication ได้\n1. การกำหนด Order Set ให้ใช้ได้เฉพาะวิชาชีพ เฉพาะแพทย์ หรือกำหนดให้ใช้ได้ทั้ง รพ. หรือทั้งสองแบบ",
