            "no": "5.20",
            "topic": "๑.๕.๘  การส่งต่อ (Refer)",
            "question": "๑.๕.๘.๔ ส่งต่อภายนอก โดยประกอบด้วยรายละเอียด ดังนี้ \n- สามารถเชื่อมต่อระบบ e-Referral ได้ \n- สามารถแสดง/บันทึก/ยกเลิก/แก้ไขข้อมูลส่งต่อภายนอกได้ \n- สามารถแสดงเลขที่ส่งต่อ ระบบดำเนินการเพิ่มข้อมูลอัตโนมัติ \n- สามารถแสดงวันที่มารับบริการ ระบบดำเนินการเพิ่มข้อมูลอัตโนมัติ \n- สามารถเลือกสถานพยาบาลที่ส่งไป โดยระบบจะแสดงข้อมูลสถานพยาบาล หรือสามารถค้นหาข้อมูลสถานพยาบาลโดยการพิมพ์ข้อมูล เมื่อค้นหาสำเร็จ ระบบจะแสดงผลการค้นหาสถานพยาบาล \n- สามารถดึงข้อมูลอัตโนมัติของข้อมูลผู้รับบริการที่สำคัญ ได้แก่ ข้อมูลพื้นฐานผู้รับบริการ ประวัติเจ็บป่วย และการวินิจฉัยโรค \n- สามารถกรอกข้อมูลเหตุผลในการส่งต่อภายนอกได้ \n- สามารถพิมพ์เอกสารได้\n1. ขอตัวอย่างเอกสาร\n2. กรณีส่งต่อคลินิกอื่น ที่ไม่อยู่ในศูนย์เดียวกัน จะส่งข้อมูลและแสดงข้อมูลอย่างไร\n3. กรณีส่งต่อภายนอก มีค่าใช้จ่ายในการส่งต่อหรือไม่ เช่น ค่ารถ ค่าเดินทาง เป็นต้น ถ้ามี คิดค่าใช้จ่ายอย่างไร และมีขั้นตอนในการกรอกข้อมูลอย่างไร\n4. ขอทราบกระบวนการ และข้อมูลตัวอย่างหน้าจอ e-Referral ในการรับเข้าและส่งออกภายนอก",
