            "question": "๑.๘.๑.๓ สามารถแสดงรายการค่ารักษาพยาบาลทั้งหมดของผู้รับบริการ ได้แก่ ยอดเงินค่ารักษาพยาบาลทั้งหมด ยอดเรียกเก็บ ยอดลดหย่อน ยอดที่ต้องชำระ ยอดรับชำระ ยอดค้างชำระ ยอดเงินที่ต้องชำระ\n1. มีการคำนวณค่าใช้จ่าย Vat หรือไม่ ถ้ามีคิดเป็นกี่ % (เปอร์เซ็นต์)\n2. มีการคำนวณค่าใช้จ่ายอย่างไรบ้าง",
