            "question": "๑.๙.๒.๕ สามารถพิมพ์ฉลากยา โดยจะเป็นการสรุปวิธีการใช้ยาของยาแต่ละประเภท พร้อมฟังก์ชันการพิมพ์วิธีการใช้ยาภาษาอังกฤษ การพิมพ์วิธีการใช้ยาพิเศษ\n1. ขอตัวอย่างฉลากยา\n2. ขอตัวอย่างเอกสารการใช้ยาภาษาอังกฤษ \n3. ขอตัวอย่างเอกสารวิธีการใช้ยาพิเศษ",
