            "question": "๑.๙.๒.๑๐ สามารถตรวจสอบและแจ้งเตือนให้ห้องยาทราบเมื่อแพทย์มีการแก้ไขหรือยกเลิกการสั่งยาและเวชภัณฑ์ รวมถึงการแก้ไข วิธีการใช้ยา จำนวนยา\n1. ปัจจุบันระบบทำการพัฒนาในรูปแบบแพทย์ไม่สามารถแก้ไข/ยกเลิกการสั่งยาและเวชภัณฑ์ได้ หากมีการสรุปการรักษาแล้ว\n2. กรณีที่มีการแก้ไข ให้เภสัชทำการแก้ไข หรือส่งกลับให้แพทย์ทำการแก้ไข ถูกต้องหรือไม่",
