            "question": "๑.๑๙.๔ สามารถจัดการข้อมูลการตรวจสุขภาพ เช่น ข้อมูลคำสั่งตรวจ ผู้ใช้งานนำรายชื่อผู้รับบริการตรวจมานำเข้า (Import) พร้อมทำการลงรายการตรวจรอล่วงหน้าได้\n1. ขอข้อมูล Template ที่ต้องการใช้นำเข้าระบบ",
