            "id": "phcis-28-5",
            "no": "31.5",
            "topic": "",
            "question": "๑.๑๙.๖ รองรับการเชื่อมต่อเครื่องอ่านบัตรประชาชน เพื่อสร้างข้อมูลของผู้รับบริการได้\n1. หน่วยงานสร้างข้อมูลผู้รับบริการได้เอง หรือต้องผ่านเวชระเบียนเท่านั้น\n2. กระบวนการขั้นตอนการดำเนินงานเป็นอย่างไร\n3. มีการตรวจสุขภาพเคลื่อนที่หรือไม่ ในกรณีมีที่มีการบันทึกข้อมูลย้อนหลังหรือไม่",
