            "question": "๔. มีกระบวนการดำเนินงานที่ใช้ในการบริหารจัดการการขอความยินยอมจากเจ้าของข้อมูลส่วนบุคคล\nคำถาม\n1. ขอรายละเอียดกระบวนการดำเนินงานที่ใช้ในการบริหารจัดการการขอความยินยอมจากเจ้าของข้อมูลส่วนบุคคล และต้องขอความยินยอมใหม่ในกรณีใด\n2. ข้อมูลใดต้องขอความยินยอมบ้าง\n3. ขอแบบฟอร์มความยินยอม\n4. กรณีที่เป็นเด็กอายุต่ำกว่า 20 ปี จะมีกระบวนการเก็บข้อมูลอย่างไร\n5. กรณีพ่อแม่เสียชีวิต การเก็บข้อมูลของเด็ก จะแตกต่างจากเดิมหรือไม่ อย่างไร",
            "types": [
              "กระบวนการทำงาน",
              "ข้อมูล",
              "ฟอร์ม"
            ],
