            "question": "๘. มีช่องทางให้เจ้าหน้าที่บันทึกเปลี่ยนแปลงข้อมูลการให้ความยินยอมจากเอกสารการให้หรือเพิกถอนความยินยอมของเจ้าของข้อมูลส่วนบุคคล\n1. ในกรณีที่มีการเพิกถอน ใช้ช่องทางใด สามารถทำได้ด้วยตนเองหรือไม่ในการเพิกถอน\n2. ต้องเก็บประวัติ(log)ด้วยไหมว่าว่าเปลี่ยนแปลงข้อมูลเวลาไหนโดยใคร",
