            "question": "๑๖.๒. สามารถระบุได้ว่า ผู้รับบริการรายใด ให้การยินยอมเรื่องใดบ้าง และ ไม่ให้การยินยอมเรื่องใดบ้าง เป็นรายบุคคล\n1. ขอรายละเอียดและตัวอย่าง",
